    toggle.textContent = settings.enabled ? "×3 · Đang bật" : "×3 · Đã tắt";
    toggle.dataset.enabled = String(settings.enabled);
    toggle.title = settings.enabled ? "Dừng tự gửi sticker" : "Bật tự gửi sticker";
